using SendGrid;
using SendGrid.Helpers.Mail;

public async Task SendWelcomeEmailAsync(string toEmail, string name)
{
    var apiKey = Environment.GetEnvironmentVariable("SENDGRID_API_KEY");
    var client = new SendGridClient(apiKey);

    var from = new EmailAddress("no-reply@myapp.com", "MyApp");
    var to = new EmailAddress(toEmail, name);
    var msg = MailHelper.CreateSingleEmail(
        from,
        to,
        "Welcome to MyApp",
        "Thanks for joining, " + name + "!",
        "<h1>Welcome, " + name + "!</h1>"
    );

    var response = await client.SendEmailAsync(msg);
    Console.WriteLine(response.StatusCode);
}

var msg = new SendGridMessage();
msg.SetFrom(new EmailAddress("no-reply@myapp.com", "MyApp"));
